//! Generate, check and convert pruning tables.
//!
//! ```text
//! gen <k> <base|auto> <out> [-t threads] [--parts N] [--dfs] [k:base:path ...]
//!     Generate hk (k = 0..11) into the file <out> (data, then a trailer
//!     with k, base, distribution and checksum). `auto` picks the measured
//!     best base for k. --parts N generates N row ranges one after the other
//!     (memory: 1/N of the table; time: up to N times). h0 and h11 are
//!     generated by BFS (and can derive smaller tables in the same run:
//!     k:base:path), other k by depth-first passes (`gen::dfs`; --dfs uses
//!     them for h0 too, a check of one generator against the other).
//!     (`gen generate ...` is the same.)
//! gen stamp <path> <k> <base>
//!     Add a trailer to a table file made before trailers (in place: the
//!     trailer goes after the data, which is never written).
//! gen check <path> [--json]
//!     Recompute the distribution and checksum and compare with the trailer.
//! gen derive <source> <k> <out>
//!     hk of the source's base from a table of a larger k (min-collapse).
//! gen compare <a> <b>
//!     Compare table a with table b (of the same base; b's k at least a's,
//!     collapsed to a's k on the fly).
//! ```
//! On a terminal, long steps show a progress bar on stderr; elsewhere (logs,
//! pipes) stderr has the progress lines only.

// No intentional panics in shipped code (user request; asserts, which no
// lint covers, are checked by tests/no_runtime_panics.rs).
#![cfg_attr(
    not(test),
    deny(
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::unreachable,
        clippy::todo,
        clippy::unimplemented
    )
)]

use anyhow::Context as _;
use clap::{Args, Parser, Subcommand};
use cubeopt::cli::{self, preflight, BadInput, Verbosity};
use cubeopt::gen::progress;
use cubeopt::gen::{collapse, dfs};
use cubeopt::tables::file::{self, LoadMode, LoadOptions, Trailer};
use cubeopt::tables::{default_base, distribution, h48_bytes, h48_rows, Cocsep};
use cubeopt::tables::{H48Meta, H48Table, Memory, ROW_BYTES};
use std::io::IsTerminal as _;
use std::process::ExitCode;
use std::time::Instant;

/// Generate, check and convert pruning tables (`hK` files).
#[derive(Parser, Debug)]
#[command(name = "gen", version, args_conflicts_with_subcommands = true)]
struct Cli {
    #[command(subcommand)]
    command: Option<Command>,
    /// (`gen <K> <BASE> <OUT>`: the same as `gen generate <K> <BASE> <OUT>`.)
    #[command(flatten)]
    generate: Option<GenerateArgs>,
    #[command(flatten)]
    verbosity: Verbosity,
    /// Print a shell completion script.
    #[arg(long, value_name = "SHELL", exclusive = true, hide = true)]
    completions: Option<clap_complete::Shell>,
}

#[derive(Subcommand, Debug)]
enum Command {
    /// Generate hK into a file (the default command).
    Generate(GenerateArgs),
    /// Add a trailer to a table file made before trailers (in place: the
    /// trailer goes after the data, which is never written).
    Stamp {
        /// The table file.
        path: String,
        /// Its K (0..11).
        #[arg(value_parser = clap::value_parser!(u32).range(0..=11))]
        k: u32,
        /// Its base (0..12).
        #[arg(value_parser = clap::value_parser!(u8).range(0..=12))]
        base: u8,
    },
    /// Recompute a table's distribution and checksum and compare them with
    /// its trailer.
    Check {
        /// The table file.
        path: String,
        /// Print the result as JSON.
        #[arg(long)]
        json: bool,
    },
    /// hK of the source's base from a table of a larger k (min-collapse).
    Derive {
        /// The table file to derive from.
        source: String,
        /// The K of the new table (at most the source's).
        #[arg(value_parser = clap::value_parser!(u32).range(0..=11))]
        k: u32,
        /// The table file to write.
        out: String,
        /// Skip the checks of disk space and memory before the run.
        #[arg(long)]
        force: bool,
    },
    /// Compare table A with table B (of the same base; B's k at least A's,
    /// collapsed to A's k on the fly).
    Compare {
        /// A table file.
        a: String,
        /// A table file of the same base and at least A's K.
        b: String,
    },
}

#[derive(Args, Debug)]
struct GenerateArgs {
    /// The table: hK for K = 0..11 (larger: faster solves, more memory:
    /// h8 3.6 GiB, h11 58 GiB).
    #[arg(value_parser = clap::value_parser!(u32).range(0..=11))]
    k: u32,
    /// The base (0..12), or `auto` for the measured best for K.
    #[arg(value_name = "BASE|auto", value_parser = parse_base)]
    base: Base,
    /// The table file to write (data, then a trailer with K, base,
    /// distribution and checksum).
    out: String,
    /// Threads.
    #[arg(
        short,
        long,
        env = "CUBEOPT_THREADS",
        default_value_t = cubeopt::thread_count(),
        value_parser = cli::positive(),
    )]
    threads: usize,
    /// Generate N row ranges one after the other (memory: 1/N of the table;
    /// time: up to N times; depth-first generation only).
    #[arg(long, value_name = "N", default_value_t = 1, value_parser = clap::value_parser!(u64).range(1..))]
    parts: u64,
    /// Generate h0 by depth-first passes (as h1..h10), not by BFS: a check
    /// of one generator against the other.
    #[arg(long)]
    dfs: bool,
    /// Smaller tables to derive in the same run (BFS only: K 0 or 11).
    #[arg(value_name = "K:BASE:PATH", value_parser = parse_derived)]
    derived: Vec<(u32, u8, String)>,
    /// Skip the checks before the run: room for the files (free space, or
    /// free huge pages on hugetlbfs) and memory (`MemAvailable`).
    #[arg(long)]
    force: bool,
}

/// A base: a number or `auto`.
#[derive(Clone, Copy, Debug)]
enum Base {
    Auto,
    Fixed(u8),
}

/// `BASE|auto`.
fn parse_base(text: &str) -> Result<Base, String> {
    match text {
        "auto" => Ok(Base::Auto),
        _ => match text.parse::<u8>() {
            Ok(base @ 0..=12) => Ok(Base::Fixed(base)),
            _ => Err("expected 0..12 or auto".to_string()),
        },
    }
}

/// `K:BASE:PATH` of a derived table.
fn parse_derived(text: &str) -> Result<(u32, u8, String), String> {
    let parts: Vec<&str> = text.splitn(3, ':').collect();
    let [k, base, path] = parts[..] else {
        return Err("expected K:BASE:PATH".to_string());
    };
    match (k.parse::<u32>(), base.parse::<u8>()) {
        (Ok(k @ 0..=11), Ok(base @ 0..=12)) => Ok((k, base, path.to_string())),
        _ => Err("expected K:BASE:PATH with K 0..11 and BASE 0..12".to_string()),
    }
}

/// Tables read as sources are mapped (no copy: they may be large, and on
/// hugetlbfs they are in memory already), and read once in order (no
/// prefault: the page cache need not hold all of a table larger than RAM).
fn open_source(path: &str) -> anyhow::Result<H48Table> {
    let options = LoadOptions {
        mode: LoadMode::Map,
        prefault: file::is_hugetlbfs(path),
        ..LoadOptions::default()
    };
    log::info!("{path}: mapped (prefault: {})", options.prefault);
    H48Table::open_with(path, &options).with_context(|| format!("cannot open {path}"))
}

/// Peak resident memory of this process, in GiB (0 where unknown: WASI).
#[cfg(not(unix))]
fn peak_rss_gib() -> f64 {
    0.0
}

/// Peak resident memory of this process, in GiB.
#[cfg(unix)]
fn peak_rss_gib() -> f64 {
    // SAFETY: `usage` is a valid out-pointer.
    let max_rss = unsafe {
        let mut usage: libc::rusage = std::mem::zeroed();
        libc::getrusage(libc::RUSAGE_SELF, &raw mut usage);
        usage.ru_maxrss
    };
    // (Linux reports KiB, macOS bytes.)
    let unit = if cfg!(target_os = "macos") {
        1u64 << 30
    } else {
        1 << 20
    };
    #[expect(clippy::cast_precision_loss, reason = "a report")]
    let gib = max_rss as f64 / unit as f64;
    gib
}

fn gib(bytes: u64) -> f64 {
    #[expect(clippy::cast_precision_loss, reason = "a report")]
    let g = bytes as f64 / f64::from(1u32 << 30);
    g
}

/// The progress bar of a long step, on stderr if it is a terminal (never in
/// logs or pipes).
fn progress_bar(message: String, total: u64) -> Option<indicatif::ProgressBar> {
    if !std::io::stderr().is_terminal() {
        return None;
    }
    let style = indicatif::ProgressStyle::with_template(
        "{spinner} {msg} [{elapsed_precise}] [{wide_bar}] {percent}% (eta {eta})",
    )
    .unwrap_or_else(|_| indicatif::ProgressStyle::default_bar());
    let bar = indicatif::ProgressBar::new(total)
        .with_style(style)
        .with_message(message);
    bar.enable_steady_tick(std::time::Duration::from_millis(200));
    Some(bar)
}

/// A spinner (with the elapsed time) for a step without progress reports
/// (reading a whole table), on a terminal.
fn spinner(message: String) -> Option<indicatif::ProgressBar> {
    let bar = progress_bar(message, 0)?;
    let style = indicatif::ProgressStyle::with_template("{spinner} {msg} [{elapsed_precise}]")
        .unwrap_or_else(|_| indicatif::ProgressStyle::default_spinner());
    bar.set_style(style);
    Some(bar)
}

/// Shows the generators' progress (`cubeopt::gen::progress`) on a progress
/// bar, their lines above it.
struct BarReporter(indicatif::ProgressBar);

impl progress::Reporter for BarReporter {
    fn line(&self, line: &str) {
        self.0.println(line);
    }

    fn start(&self, name: &str, total: u64) {
        self.0.reset();
        self.0.set_length(total);
        self.0.set_message(name.to_string());
    }

    fn advance(&self, units: u64) {
        self.0.inc(units);
    }
}

/// Print `value` as one line of JSON (stdout flushes at the newline).
fn print_json(value: &impl serde::Serialize) -> anyhow::Result<()> {
    println!("{}", serde_json::to_string(value)?);
    Ok(())
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    if let Some(shell) = cli.completions {
        cli::print_completions::<Cli>(shell);
        return ExitCode::SUCCESS;
    }
    cli.verbosity.init_logging();
    let result = match (cli.command, cli.generate) {
        (Some(Command::Generate(args)), _) | (None, Some(args)) => generate(&args),
        (Some(Command::Stamp { path, k, base }), _) => stamp(&path, k, base),
        (Some(Command::Check { path, json }), _) => check(&path, json),
        (
            Some(Command::Derive {
                source,
                k,
                out,
                force,
            }),
            _,
        ) => derive(&source, k, &out, force),
        (Some(Command::Compare { a, b }), _) => compare(&a, &b),
        // (clap asks for <K> <BASE> <OUT> before.)
        (None, None) => Err(BadInput("a command or <K> <BASE> <OUT> is needed".to_string()).into()),
    };
    cli::exit_status("gen", result)
}

fn generate(args: &GenerateArgs) -> anyhow::Result<ExitCode> {
    let k = args.k;
    let base = match args.base {
        Base::Auto => default_base(k),
        Base::Fixed(base) => base,
    };
    let (out, threads, parts) = (&args.out, args.threads, args.parts);
    let force_dfs = args.dfs;
    if force_dfs && k != 0 {
        return Err(BadInput(
            "--dfs is for h0 (h1..h10 are always made by depth-first passes)".to_string(),
        )
        .into());
    }
    let derived: Vec<(u32, u8, Option<String>)> = args
        .derived
        .iter()
        .map(|(k, base, path)| (*k, *base, Some(path.clone())))
        .collect();
    if !derived.is_empty() && k != 0 && k != 11 {
        return Err(BadInput(
            "derived tables only with the BFS generators (k 0 or 11)".to_string(),
        )
        .into());
    }
    let bfs = (k == 0 && !force_dfs) || k == 11;
    if args.force {
        log::info!("preflight: skipped (--force)");
    } else {
        preflight_generate(k, out, parts, bfs, &args.derived)?;
    }
    let t = Instant::now();
    let corners = Cocsep::generate()?;
    // (On a terminal: a progress bar, with the progress lines above it.)
    let bar = progress_bar(format!("h{k}"), 0);
    if let Some(bar) = &bar {
        progress::install(Box::new(BarReporter(bar.clone())));
    }
    progress::line(format_args!(
        "[gen] h{k} base {base}: {:.2} GiB, {threads} threads{}",
        gib(h48_bytes(k)),
        if parts > 1 {
            format!(", {parts} parts")
        } else {
            String::new()
        }
    ));
    let trailer = if bfs {
        // BFS (true coordinates). On hugetlbfs or /dev/shm the table is
        // generated in place; elsewhere in memory, then written.
        let in_place = file::is_hugetlbfs(out) || out.starts_with("/dev/shm");
        log::info!(
            "BFS, {}, {} derived tables",
            if in_place {
                "in place"
            } else {
                "in memory, then written"
            },
            derived.len()
        );
        let (table, ds) = cubeopt::generate(
            &corners,
            k,
            base,
            in_place.then_some(out.as_str()),
            &derived,
            threads,
        )?;
        for d in &ds {
            progress::line(format_args!(
                "h{} base {} distribution {:?}",
                d.meta.k,
                d.meta.base,
                d.distribution()?
            ));
        }
        if in_place {
            file::read_trailer(out)?.context("no trailer written")?
        } else {
            let trailer = table.trailer(threads)?;
            write_table(out, table.memory.bytes()?, &trailer)?;
            trailer
        }
    } else {
        log::info!("depth-first passes, {parts} parts");
        generate_dfs(&corners, k, base, threads, parts, out)?
    };
    if let Some(bar) = bar {
        bar.finish_and_clear();
    }
    eprintln!(
        "generated in {:.1}s, peak memory {:.2} GiB",
        t.elapsed().as_secs_f64(),
        peak_rss_gib()
    );
    eprintln!(
        "h{k} base {base} distribution {:?}",
        trailer.distribution.unwrap_or_default()
    );
    Ok(ExitCode::SUCCESS)
}

/// `gen::dfs` in `parts` row ranges, each in anonymous memory, written into
/// `out` when done; then the trailer.
fn generate_dfs(
    corners: &Cocsep,
    k: u32,
    base: u8,
    threads: usize,
    parts: u64,
    out: &str,
) -> anyhow::Result<Trailer> {
    let settings = dfs::Settings {
        k,
        base,
        threads,
        prefix_depth: dfs::PREFIX_DEPTH.min(base.saturating_add(2)),
        verbose: true,
    };
    let generator = dfs::Generator::new(corners, settings)?;
    let rows = h48_rows(k);
    let data_bytes = h48_bytes(k);
    let f = create_table_file(out, data_bytes)?;
    let mut dist = [0u64; 4];
    let mut hashes = Vec::new();
    // Parts of whole 1 MiB (8192 rows), so that writes stay page aligned.
    let per = rows.div_ceil(parts.max(1)).next_multiple_of(8192).min(rows);
    let mut start = 0;
    while start < rows {
        let range = start..(start + per).min(rows);
        let len = usize::try_from((range.end - range.start) * ROW_BYTES)?;
        let mem = Memory::anonymous(len)?;
        let part = dfs::Part {
            words: mem.words()?,
            first_slot: range.start * 512,
            end_slot: range.end * 512,
        };
        generator.generate(&range, &part)?;
        for (d, x) in dist.iter_mut().zip(distribution(part.words, threads)?) {
            *d += x;
        }
        // (The part's `len` bytes. Parts start at whole checksum chunks: 8192
        // rows are 1 MiB.)
        let bytes = mem.bytes()?;
        hashes.extend(file::chunk_hashes(bytes, threads)?);
        let tw = Instant::now();
        write_at(&f, out, bytes, range.start * ROW_BYTES)?;
        progress::line(format_args!(
            "[gen h{k}] rows {}..{} written in {:.1}s",
            range.start,
            range.end,
            tw.elapsed().as_secs_f64()
        ));
        start = range.end;
    }
    drop(f);
    let trailer = Trailer {
        k,
        base,
        data_bytes,
        distribution: Some(dist),
        checksum: Some(file::combine_hashes(data_bytes, &hashes)),
    };
    file::write_trailer(out, &trailer)?;
    Ok(trailer)
}

/// Create (or truncate) a table file with room for `data_bytes` and a
/// trailer.
fn create_table_file(path: &str, data_bytes: u64) -> anyhow::Result<std::fs::File> {
    let f = std::fs::File::create(path).with_context(|| format!("cannot create {path}"))?;
    f.set_len(file::file_bytes(data_bytes, false))
        .with_context(|| format!("cannot size {path}"))?;
    Ok(f)
}

/// Write all of `data` at `offset` of `f`.
#[cfg(unix)]
fn write_all_at(f: &std::fs::File, data: &[u8], offset: u64) -> std::io::Result<()> {
    std::os::unix::fs::FileExt::write_all_at(f, data, offset)
}

/// Write all of `data` at `offset` of `f` (a seek and a write, where there
/// is no positioned write: WASI's is unstable).
#[cfg(not(unix))]
fn write_all_at(mut f: &std::fs::File, data: &[u8], offset: u64) -> std::io::Result<()> {
    use std::io::{Seek, Write};
    f.seek(std::io::SeekFrom::Start(offset))?;
    f.write_all(data)
}

/// Write `data` at `offset` of `f` (the file at `path`), in pieces whose
/// writeback starts as soon as each is written and which are then dropped
/// from the page cache (a table is written once, and read back later if at
/// all): the dirty page cache stays small, and the disk stays busy.
fn write_at(f: &std::fs::File, path: &str, data: &[u8], offset: u64) -> anyhow::Result<()> {
    let piece = 64 << 20;
    for (i, chunk) in data.chunks(piece).enumerate() {
        let at = offset + (i * piece) as u64;
        write_all_at(f, chunk, at).with_context(|| format!("cannot write {path}"))?;
        #[cfg(target_os = "linux")]
        // Start this piece's writeback; wait for the previous piece's and
        // drop it from the page cache.
        // SAFETY: writeback requests and advice on an open file.
        unsafe {
            use std::os::unix::io::AsRawFd;
            let fd = f.as_raw_fd();
            // (Requests and advice only: skipped for ranges beyond `off_t`.)
            let range =
                |at: u64, len: usize| Some((i64::try_from(at).ok()?, i64::try_from(len).ok()?));
            if let Some((start, len)) = range(at, chunk.len()) {
                libc::sync_file_range(fd, start, len, libc::SYNC_FILE_RANGE_WRITE);
            }
            let previous = at.checked_sub(piece as u64).filter(|_| i > 0);
            if let Some((start, len)) = previous.and_then(|at| range(at, piece)) {
                let wait = libc::SYNC_FILE_RANGE_WAIT_BEFORE
                    | libc::SYNC_FILE_RANGE_WRITE
                    | libc::SYNC_FILE_RANGE_WAIT_AFTER;
                libc::sync_file_range(fd, start, len, wait);
                libc::posix_fadvise(fd, start, len, libc::POSIX_FADV_DONTNEED);
            }
        }
    }
    f.sync_data()
        .with_context(|| format!("cannot sync {path}"))?;
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::io::AsRawFd;
        let tail = offset + (data.len().saturating_sub(1) / piece * piece) as u64;
        if let Ok(tail) = libc::off_t::try_from(tail) {
            // SAFETY: advice on an open file.
            unsafe {
                libc::posix_fadvise(f.as_raw_fd(), tail, 0, libc::POSIX_FADV_DONTNEED);
            }
        }
    }
    Ok(())
}

fn write_table(path: &str, data: &[u8], trailer: &Trailer) -> anyhow::Result<()> {
    let data = data
        .get(..usize::try_from(trailer.data_bytes)?)
        .context("less data than the trailer says")?;
    let f = create_table_file(path, trailer.data_bytes)?;
    write_at(&f, path, data, 0)?;
    drop(f);
    file::write_trailer(path, trailer)?;
    Ok(())
}

/// Drop a file from the page cache.
fn drop_cache(path: &str) {
    #[cfg(target_os = "linux")]
    if let Ok(f) = std::fs::File::open(path) {
        use std::os::unix::io::AsRawFd;
        // SAFETY: advice on an open file.
        unsafe {
            libc::posix_fadvise(f.as_raw_fd(), 0, 0, libc::POSIX_FADV_DONTNEED);
        }
    }
    #[cfg(not(target_os = "linux"))]
    let _ = path;
}

fn stamp(path: &str, k: u32, base: u8) -> anyhow::Result<ExitCode> {
    let data_bytes = h48_bytes(k);
    let flen = std::fs::metadata(path)
        .with_context(|| format!("cannot read {path}"))?
        .len();
    if flen < data_bytes + file::TRAILER_BYTES || flen >= data_bytes + 2 * file::HUGE_PAGE {
        anyhow::bail!(
            "{path} has {flen} bytes, h{k} needs {data_bytes} and room for a trailer after \
             them (copy it to a file of {} bytes first)",
            data_bytes + file::TRAILER_BYTES
        );
    }
    if let Ok(Some(t)) = file::read_trailer(path) {
        anyhow::bail!("{path} already has a trailer: {t:?}");
    }
    let progress = spinner(format!("stamping {path}"));
    let data = Memory::map_read_only(path, usize::try_from(data_bytes)?, true)
        .with_context(|| format!("cannot map {path}"))?;
    let table = H48Table {
        memory: data,
        meta: H48Meta { k, base },
    };
    let trailer = table.trailer(cubeopt::thread_count())?;
    drop(table);
    file::write_trailer(path, &trailer)?;
    drop_cache(path);
    if let Some(progress) = progress {
        progress.finish_and_clear();
    }
    println!("stamped {path}: {trailer:?}");
    Ok(ExitCode::SUCCESS)
}

/// `gen check --json`.
#[derive(serde::Serialize)]
struct CheckReport<'a> {
    path: &'a str,
    k: u32,
    base: u8,
    /// Entries per code (0..3) in the data.
    distribution: [u64; 4],
    /// The data's checksum (16 hex digits).
    checksum: String,
    /// The trailer's (null if it records none).
    trailer_distribution: Option<[u64; 4]>,
    trailer_checksum: Option<String>,
    /// Whether the data matches all the trailer records.
    ok: bool,
}

fn check(path: &str, json: bool) -> anyhow::Result<ExitCode> {
    let table = open_source(path)?;
    let Ok(Some(want)) = file::read_trailer(path) else {
        anyhow::bail!("{path} has no trailer (k and base from its meta file)");
    };
    let progress = spinner(format!("checking {path}"));
    let got = table.trailer(cubeopt::thread_count())?;
    drop(table);
    drop_cache(path);
    if let Some(progress) = progress {
        progress.finish_and_clear();
    }
    let distribution = got.distribution.unwrap_or_default();
    let distribution_ok = want.distribution.is_none() || want.distribution == got.distribution;
    let checksum_ok = want.checksum.is_none() || want.checksum == got.checksum;
    let ok = distribution_ok && checksum_ok;
    if json {
        let hex = |c: u64| format!("{c:016x}");
        print_json(&CheckReport {
            path,
            k: got.k,
            base: got.base,
            distribution,
            checksum: got.checksum.map(hex).unwrap_or_default(),
            trailer_distribution: want.distribution,
            trailer_checksum: want.checksum.map(hex),
            ok,
        })?;
    } else {
        println!("{path}: h{} base {}", got.k, got.base);
        println!("distribution {distribution:?}");
        if !distribution_ok {
            println!("MISMATCH distribution: trailer {:?}", want.distribution);
        }
        if !checksum_ok {
            println!(
                "MISMATCH checksum: trailer {:?}, data {:?}",
                want.checksum, got.checksum
            );
        }
        if ok {
            println!("ok");
        }
    }
    Ok(if ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    })
}

/// Before generating hK into `out` (and the `derived` tables): room for the
/// files, and memory for the tables built in memory (BFS: the table unless
/// it is built in place on hugetlbfs, and each derived table not on
/// hugetlbfs, which are written through mappings; depth-first: one part)
/// and the generator's own.
fn preflight_generate(
    k: u32,
    out: &str,
    parts: u64,
    bfs: bool,
    derived: &[(u32, u8, String)],
) -> anyhow::Result<()> {
    let names: Vec<String> = std::iter::once(k)
        .chain(derived.iter().map(|d| d.0))
        .map(|k| format!("h{k}"))
        .collect();
    let mut outputs = vec![(names[0].as_str(), out, h48_bytes(k))];
    for ((dk, _, path), name) in derived.iter().zip(&names[1..]) {
        outputs.push((name.as_str(), path.as_str(), h48_bytes(*dk)));
    }
    let hint = "free space, or choose another OUT or a smaller k";
    let rooms = preflight::files(&outputs, hint)?;
    let in_memory = |i: usize| {
        rooms[i]
            .as_ref()
            .is_none_or(|room| room.huge_page.is_none())
    };
    let tables: u64 = if bfs {
        (0..outputs.len())
            .filter(|&i| in_memory(i))
            .map(|i| outputs[i].2)
            .sum()
    } else {
        let rows = h48_rows(k);
        rows.div_ceil(parts.max(1)).next_multiple_of(8192).min(rows) * ROW_BYTES
    };
    let hint = if bfs {
        "free memory, generate on hugetlbfs, or use a smaller k (--force skips this check)"
    } else {
        "use --parts N (1/N of the memory), free memory or use a smaller k (--force skips \
         this check)"
    };
    preflight::memory(
        &format!("generating {}", names.join(" and ")),
        tables + preflight::GENERATOR_OVERHEAD,
        hint,
    )
}

fn derive(source: &str, k: u32, out: &str, force: bool) -> anyhow::Result<ExitCode> {
    if force {
        log::info!("preflight: skipped (--force)");
    } else {
        let name = format!("h{k}");
        preflight::files(
            &[(&name, out, h48_bytes(k))],
            "free space, or choose another OUT",
        )?;
        let hint = "free memory or derive a smaller k (--force skips this check)";
        preflight::memory(
            &format!("deriving {name}"),
            h48_bytes(k) + preflight::GENERATOR_OVERHEAD,
            hint,
        )?;
    }
    let src = open_source(source)?;
    if k > src.meta.k {
        let source_k = src.meta.k;
        return Err(BadInput(format!("{source} is h{source_k}: no h{k} from it")).into());
    }
    let t = Instant::now();
    let progress = spinner(format!("deriving h{k} from {source}"));
    let table = collapse::derive(&src, k, cubeopt::thread_count())?;
    let trailer = table.trailer(cubeopt::thread_count())?;
    write_table(out, table.memory.bytes()?, &trailer)?;
    drop(src);
    drop_cache(source);
    if let Some(progress) = progress {
        progress.finish_and_clear();
    }
    eprintln!(
        "h{k} base {} derived in {:.1}s: distribution {:?}",
        trailer.base,
        t.elapsed().as_secs_f64(),
        trailer.distribution.unwrap_or_default()
    );
    Ok(ExitCode::SUCCESS)
}

fn compare(a: &str, b: &str) -> anyhow::Result<ExitCode> {
    let (ta, tb) = (open_source(a)?, open_source(b)?);
    if ta.meta.base != tb.meta.base || ta.meta.k > tb.meta.k {
        return Err(BadInput(format!(
            "{a} is h{} base {}, {b} h{} base {}: compare needs the same base, {b}'s k at least {a}'s",
            ta.meta.k, ta.meta.base, tb.meta.k, tb.meta.base
        ))
        .into());
    }
    let progress = spinner(format!("comparing {a} with {b}"));
    let d = collapse::compare(&ta, &tb, cubeopt::thread_count())?;
    if let Some(progress) = progress {
        progress.finish_and_clear();
    }
    println!(
        "{a} (h{} base {}) vs {b} (h{} base {}): {d:?}",
        ta.meta.k, ta.meta.base, tb.meta.k, tb.meta.base
    );
    drop((ta, tb));
    drop_cache(a);
    drop_cache(b);
    if d.codes != 0 || d.group_minima != 0 {
        println!("DIFFERENT");
        return Ok(ExitCode::FAILURE);
    }
    println!("same");
    Ok(ExitCode::SUCCESS)
}
